(()=>{'use strict';const CFG='taglio-bundle-config-v11',PROG='taglio-bundle-work-v11';let bw=null,current=null;const controls=document.createElement('div');controls.className='bundleControls';controls.innerHTML='<label>Verghe per taglio sega<select id="bundleMode"><option value="auto">Auto — consiglia l’app</option>'+Array.from({length:10},(_,i)=>`<option value="${i+1}">Fino a ${i+1} verghe insieme</option>`).join('')+'</select></label><label>Massimo ammesso per questa sezione<select id="bundleLimit">'+Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===4?'selected':''}>${i+1}</option>`).join('')+'</select></label><p class="hint">5 è il valore iniziale, non una verifica della capacità della sega. Imposta il limite effettivo della macchina per questa sezione. Tagli simultanei solo su barre allineate con stessa lunghezza iniziale.</p>';$('stock').closest('label').after(controls);function config(){return{mode:$('bundleMode').value,limit:Number($('bundleLimit').value)}}try{const c=JSON.parse(localStorage.getItem(CFG)||'null');if(c&&Number.isInteger(c.limit)&&c.limit>=1&&c.limit<=10&&(c.mode==='auto'||/^(10|[1-9])$/.test(c.mode))){$('bundleMode').value=c.mode;$('bundleLimit').value=c.limit}}catch(e){}const baseSave=save;save=function(){baseSave();try{localStorage.setItem(CFG,JSON.stringify(config()));if(bw)localStorage.setItem(PROG,JSON.stringify(bw));else localStorage.removeItem(PROG)}catch(e){$('error').textContent='Salvataggio non disponibile: avanzamento non garantito dopo la chiusura.'}};function counts(list){const m=new Map();list.forEach(l=>m.set(l,(m.get(l)||0)+1));return m}function patternKey(b){return JSON.stringify([b.old,b.L,b.pattern])}function batchesFromBars(bars,cap){const patterns=new Map();for(const b of bars){const pattern=[...counts(b.parts)].sort((a,b)=>b[0]-a[0]),p={old:b.old,L:b.L,pattern,rem:b.rem};const key=patternKey(p);if(!patterns.has(key))patterns.set(key,{...p,n:0});patterns.get(key).n++}const out=[];for(const p of patterns.values()){let n=p.n;while(n){const width=Math.min(n,cap);out.push({old:p.old,L:p.L,pattern:p.pattern.map(x=>x.slice()),rem:p.rem,width});n-=width}}return out}function bundled(parts,stock,drops,k,h,t,target,ascending){const need=counts(parts),available=counts(drops),batches=[];function pattern(L,w){let rem=L-h-t;const cuts=[];const lengths=[...need.keys()].sort((a,b)=>ascending?a-b:b-a);for(const l of lengths){const q=Math.min(Math.floor((need.get(l)||0)/w),Math.max(0,Math.floor(rem/(l+k))));if(q){cuts.push([l,q]);rem-=q*(l+k)}}return{cuts,rem}}function take(L,maxWidth,old){let w=Math.min(target,maxWidth,...[Math.max(...need.values())]);while(w>=1){const p=pattern(L,w);if(p.cuts.length){p.cuts.forEach(([l,q])=>need.set(l,need.get(l)-q*w));batches.push({old,L,pattern:p.cuts,rem:p.rem,width:w});return w}w--}return 0}for(const L of [...available.keys()].sort((a,b)=>a-b)){let n=available.get(L);while(n&&[...need.values()].some(q=>q>0)){const used=take(L,n,true);if(!used)break;n-=used}}while([...need.values()].some(q=>q>0)){if(!take(stock,target,false))break}const bars=[];batches.forEach(b=>{const pp=b.pattern.flatMap(([l,q])=>Array(q).fill(l));for(let i=0;i<b.width;i++)bars.push({old:b.old,L:b.L,rem:b.rem,parts:pp})});return{bars,missing:[...need].flatMap(([l,q])=>Array(q).fill(l))}}function schedule(raw,cap,k,h,t){const pending=batchesFromBars(raw.bars,cap),ordered=[];let last=null,moves=0,cycles=0,production=0;while(pending.length){pending.sort((a,b)=>Number(b.pattern.some(([l])=>l===last))-Number(a.pattern.some(([l])=>l===last))||a.pattern.length-b.pattern.length||b.width-a.width);const b=pending.shift(),frequency=new Map();pending.forEach(p=>p.pattern.forEach(([l])=>frequency.set(l,(frequency.get(l)||0)+1)));const seq=b.pattern.map(p=>p.slice()).sort((a,b)=>b[0]-a[0]);const start=seq.findIndex(([l])=>l===last);if(start>=0)seq.unshift(seq.splice(start,1)[0]);if(seq.length>1){let end=seq.length-1;for(let i=start>=0?1:0;i<seq.length;i++)if((frequency.get(seq[i][0])||0)>(frequency.get(seq[end][0])||0))end=i;seq.push(seq.splice(end,1)[0])}b.ops=[];if(h>0){b.ops.push({kind:'head',cuts:1});cycles++}seq.forEach(([l,q])=>{const move=last!==l;if(last!==null&&move)moves++;b.ops.push({kind:'cut',l,cuts:q,move,pieces:q*b.width});last=l;cycles+=q;production+=q});ordered.push(b)}return{batches:ordered,missing:raw.missing,newBars:raw.bars.filter(b=>!b.old).length,oldBars:raw.bars.filter(b=>b.old).length,used:raw.bars.reduce((s,b)=>s+b.L,0),moves,cycles,production,heads:ordered.filter(b=>b.ops.some(o=>o.kind==='head')).length}}function plan(d,c){check(d);const stock=measure(d.fields.stock==='custom'?d.fields.custom:d.fields.stock),[k,h,t,min]=['kerf','head','tail','minimum'].map(k=>measure(d.fields[k]));if(!stock)throw Error('Inserisci la lunghezza della verga.');const parts=expand(d.pieces,3000,'Riga pezzi'),drops=expand(d.drops,2000,'Riga spezzoni');if(!parts.length)throw Error('Inserisci almeno una misura e quantità.');if(!Number.isInteger(c.limit)||c.limit<1||c.limit>10)throw Error('Limite sezione: da 1 a 10.');const cap=c.mode==='auto'?c.limit:Number(c.mode);if(!Number.isInteger(cap)||cap<1||cap>c.limit)throw Error('Le verghe per taglio non possono superare il limite della sezione.');const candidates=[false,true].map(reverse=>schedule(solve(parts,stock,drops,k,h,t,reverse),cap,k,h,t));const widths=c.mode==='auto'?Array.from({length:cap},(_,i)=>i+1):[cap];for(const width of widths)for(const asc of [false,true])candidates.push(schedule(bundled(parts,stock,drops,k,h,t,width,asc),cap,k,h,t));candidates.sort((a,b)=>a.missing.length-b.missing.length||a.newBars-b.newBars||a.moves-b.moves||a.cycles-b.cycles||a.batches.length-b.batches.length||a.used-b.used);return{...candidates[0],stock,k,h,t,min,total:parts.length,cap,auto:c.mode==='auto'}}function signature(d,c,r){return JSON.stringify([d,c,r.batches,r.missing])}function paint(r){current=r;const root=$('result');root.replaceChildren();$('placeholder').hidden=true;node(root,'div',r.newBars+' verghe intere da '+fmt(r.stock)+' mm','big');node(root,'p','Verghe intere e spezzoni utilizzati: '+r.newBars+' + '+r.oldBars);node(root,'div','Tagli sega: '+r.cycles+' · Spostamenti fermo per i pezzi: '+r.moves,'metric');node(root,'p','Tagli sega per pezzi: '+r.production+(r.heads?' · Tagli sega di intestatura: '+r.heads:'')+'. La prima impostazione del fermo non è conteggiata come spostamento.','hint');if(r.missing.length)node(root,'p','PIANO INCOMPLETO: '+r.missing.length+' pezzi non assegnati.','error');node(root,'p','Proposta euristica: confronta più piani, senza garanzia del minimo assoluto. Priorità a quantità complete e numero di verghe, poi spostamenti fermo e tagli sega.','hint');const progress=node(root,'p','','workProgress');function progressUpdate(){const done=bw.bars.filter(Boolean).length,total=bw.bars.length,steps=bw.ops.filter(Boolean).length;progress.textContent=(total&&done===total?(r.missing.length?'✓ BARRE ASSEGNATE COMPLETATE — piano incompleto':'✓ TAGLIO COMPLETATO'):done+' di '+total+' barre completate')+' · '+steps+'/'+bw.ops.length+' operazioni';progress.classList.toggle('allDone',total>0&&done===total)}let opIndex=0,barIndex=0,verga=0,spezzone=0;let free=0,waste=0,kerfLoss=0,trim=0,reserve=0;r.batches.forEach((b,bi)=>{const box=document.createElement('article');box.className='plan bundlePlan';node(box,'h2','Prossime verghe da preparare');node(box,'h3',b.width+' '+(b.old?'spezzoni':'verghe')+' da '+fmt(b.L)+' mm');node(box,'p','Da tagliare insieme · preparazione '+(bi+1));const opIds=b.ops.map(()=>opIndex++),barIds=Array.from({length:b.width},()=>barIndex++),opInputs=[],barInputs=[];function synchronize(persist=true){opInputs.forEach((input,i)=>{input.checked=bw.ops[opIds[i]];input.closest('label').classList.toggle('isDone',input.checked)});barInputs.forEach((input,i)=>{input.checked=bw.bars[barIds[i]];input.closest('label').classList.toggle('isDone',input.checked)});progressUpdate();if(persist)save()}b.ops.forEach((op,oi)=>{const line=document.createElement('label');line.className='checkLine operation';const input=document.createElement('input');input.type='checkbox';input.setAttribute('aria-label','Preparazione '+(bi+1)+' operazione '+(oi+1));const desc=document.createElement('span');if(op.kind==='head'){node(desc,'strong','Intesta le '+b.width+' barre');node(desc,'span','1 taglio sega · perdita totale prevista '+fmt(r.h)+' mm per barra.','opDetail')}else{node(desc,'strong',(op.move?'Sposta fermo a ':'Mantieni fermo a ')+fmt(op.l)+' mm');node(desc,'span','Esegui '+op.cuts+' tagli sega → ottieni '+op.pieces+' pezzi da '+fmt(op.l)+' mm.','opDetail');if(oi>0)node(desc,'small','Mantieni le stesse '+b.width+' barre.','opDetail')}input.onchange=()=>{bw.ops[opIds[oi]]=input.checked;if(opIds.every(i=>bw.ops[i]))barIds.forEach(i=>bw.bars[i]=true);else barIds.forEach(i=>bw.bars[i]=false);synchronize()};line.append(input,desc);box.append(line);opInputs.push(input)});node(box,'p','Avanzo per barra: '+fmt(b.rem)+' mm — '+(b.rem>0&&b.rem>=r.min?'da conservare':'sotto soglia / nullo'));const all=document.createElement('button');all.textContent='Segna queste '+b.width+' barre completate';all.onclick=()=>{opIds.forEach(i=>bw.ops[i]=true);barIds.forEach(i=>bw.bars[i]=true);synchronize()};box.append(all);barIds.forEach((id,i)=>{const line=document.createElement('label');line.className='checkLine barCheck';const input=document.createElement('input');input.type='checkbox';const name=b.old?'Spezzone '+(++spezzone):'Verga '+(++verga);input.setAttribute('aria-label',name+' tagliata');node(line,'span',name+' — tagliata');line.prepend(input);input.onchange=()=>{bw.bars[id]=input.checked;if(barIds.every(i=>bw.bars[i]))opIds.forEach(i=>bw.ops[i]=true);else if(opIds.every(i=>bw.ops[i]))opIds.forEach(i=>bw.ops[i]=false);synchronize()};box.append(line);barInputs.push(input)});root.append(box);synchronize(false);const pieces=b.pattern.reduce((s,p)=>s+p[1],0);kerfLoss+=pieces*b.width*r.k;trim+=b.width*r.h;reserve+=b.width*r.t;if(b.rem>0&&b.rem>=r.min)free+=b.rem*b.width;else waste+=b.rem*b.width});node(root,'p','Avanzi recuperabili '+fmt(free)+' mm · Lama '+fmt(kerfLoss)+' mm · Intestature '+fmt(trim)+' mm · Avanzi sotto soglia '+fmt(waste)+' mm · Riserva morsa '+fmt(reserve)+' mm.','hint');progressUpdate()}function run(){const d=data(),c=config(),r=plan(d,c),sig=signature(d,c,r),ops=r.batches.reduce((s,b)=>s+b.ops.length,0),bars=r.newBars+r.oldBars,same=bw&&bw.sig===sig&&bw.ops.length===ops&&bw.bars.length===bars;const previous=(bw&&(bw.ops.some(Boolean)||bw.bars.some(Boolean)))||(work&&work.done.some(Boolean));if(!same&&previous&&!confirm('Nuovo piano operativo: azzerare le spunte del piano precedente?'))return false;if(!same)bw={sig,ops:Array(ops).fill(false),bars:Array(bars).fill(false)};work=null;paint(r);save();return true}$('calculate').onclick=()=>{try{$('error').textContent='';if(run())$('results').scrollIntoView({behavior:'smooth'})}catch(e){$('result').replaceChildren();$('placeholder').hidden=false;$('error').textContent=e.message}};try{const w=JSON.parse(localStorage.getItem(PROG)||'null');if(w&&typeof w.sig==='string'&&Array.isArray(w.ops)&&w.ops.length<=6000&&w.ops.every(x=>typeof x==='boolean')&&Array.isArray(w.bars)&&w.bars.length<=3000&&w.bars.every(x=>typeof x==='boolean')){bw=w;const d=data(),c=config(),r=plan(d,c);if(w.sig===signature(d,c,r)&&w.ops.length===r.batches.reduce((s,b)=>s+b.ops.length,0)&&w.bars.length===r.newBars+r.oldBars)paint(r)}}catch(e){$('error').textContent='Avanzamento operativo non ripristinato: controlla i dati prima di ricalcolare.'}$('newCalculation').onclick=()=>{if(!confirm('Nuovo calcolo? Quote, parametri, piano e spunte saranno azzerati.'))return;bw=null;current=null;work=null;broken=false;load({v:6,fields:{stock:'6000',custom:'',kerf:'2',head:'0',tail:'0',minimum:'300'},pieces:[['','']],drops:[['','']]});$('bundleMode').value='auto';$('bundleLimit').value='5';changed();window.scrollTo({top:0,behavior:'smooth'})};const style=document.createElement('style');style.textContent='.bundleControls{display:grid;grid-template-columns:1.4fr 1fr;gap:10px;margin:14px 0}.bundleControls p{grid-column:1/-1;margin:0}.bundlePlan{padding:18px;margin:16px 0;break-inside:avoid}.operation{align-items:center;min-height:76px}.operation>span{min-width:0;overflow-wrap:anywhere}.operation strong{display:block;font-size:19px}.operation .opDetail{display:block;font-size:16px;font-weight:500;margin-top:7px}.barCheck{padding:10px;min-height:52px}.barCheck span{font-size:16px}.bundlePlan button{width:100%;min-height:50px}@media(min-width:741px) and (max-width:1050px){.layout{display:block}#entry .params{grid-template-columns:repeat(4,minmax(0,1fr))}.bundleControls{grid-template-columns:1fr 1fr}}@media(max-width:430px){.bundleControls{grid-template-columns:1fr}.bundleControls p{grid-column:1}.operation strong{font-size:18px}.bundlePlan{padding:12px}}';document.head.append(style);window.TaglioBundle={plan,schedule,bundled,config,run};save()})();
